const upsertPrinterErrorOccurrence = `-- name: UpsertPrinterErrorOccurrence :one
INSERT INTO printer_error_occurrences (
    id, machine_id, assignment_id, run_id, source_family, original_code, first_observed_at, last_observed_at, context, verified_description
) VALUES (
    $1, $2, $3, $4, $5, $6,
    $7, $7, $8, $9
)
ON CONFLICT (assignment_id, source_family, original_code) WHERE resolved_at IS NULL
DO UPDATE SET last_observed_at = GREATEST(printer_error_occurrences.last_observed_at, EXCLUDED.last_observed_at),
              run_id = COALESCE(EXCLUDED.run_id, printer_error_occurrences.run_id),
              context = EXCLUDED.context, updated_at = now()
RETURNING id, machine_id, assignment_id, run_id, source_family, original_code, first_observed_at, last_observed_at, resolved_at, context, verified_description, created_at, updated_at
`

type UpsertPrinterErrorOccurrenceParams struct {
	ID                  uuid.UUID
	MachineID           uuid.UUID
	AssignmentID        uuid.UUID
	RunID               *uuid.UUID
	SourceFamily        string
	OriginalCode        string
	ObservedAt          time.Time
	Context             []byte
	VerifiedDescription *string
}

func (q *Queries) UpsertPrinterErrorOccurrence(ctx context.Context, arg UpsertPrinterErrorOccurrenceParams) (PrinterErrorOccurrence, error) {
	row := q.db.QueryRow(ctx, upsertPrinterErrorOccurrence,
		arg.ID,
		arg.MachineID,
		arg.AssignmentID,
		arg.RunID,
		arg.SourceFamily,
		arg.OriginalCode,
		arg.ObservedAt,
		arg.Context,
		arg.VerifiedDescription,
	)
	var i PrinterErrorOccurrence
	err := row.Scan(
		&i.ID,
		&i.MachineID,
		&i.AssignmentID,
		&i.RunID,
		&i.SourceFamily,
		&i.OriginalCode,
		&i.FirstObservedAt,
		&i.LastObservedAt,
		&i.ResolvedAt,
		&i.Context,
		&i.VerifiedDescription,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
